public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.size() == 0) {
        return 0;
    }

    Map<String, Boolean> map = new HashMap<>();

    for (String str : strings) {
        if (str.length() <= 1) {
            return 0;
        }
        for (int i = 1; i < str.length(); i++) {
            String prefix = str.substring(0, i);
            String suffix = str.substring(i);
            if (!map.containsKey(prefix)) {
                map.put(prefix, true);
            }
            if (!map.containsKey(suffix)) {
                map.put(suffix, true);
            }
        }
    }

    for (Map.Entry<String, Boolean> entry : map.entrySet()) {
        String str = entry.getKey();
        if (entry.getValue() && !str.equals(str.substring(0, str.length() - 1))) {
            return str.length();
        }
    }
    return 0;
}

public static int countOilDeposits(char[][] grid) {
    // Initialize a set to store the unique oil deposits
    Set<String> uniqueDeposits = new HashSet<>();
    // Iterate over the grid
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            // If the current cell has oil, add it to the set
            if (grid[i][j] == '@') {
                uniqueDeposits.add(i + " " + j);
            }
        }
    }
    // Return the size of the set
    return uniqueDeposits.size();
}

public static int countOilDeposits(char[][] grid) {
    int count = 0;
    int row = grid.length;
    int column = grid[0].length;
    for (int i = 0; i < row; i++) {
        for (int j = 0; j < column; j++) {
            if (grid[i][j] == '@') {
                count++;
                grid[i][j] = '#';
                dfs(grid, i, j);
            }
        }
    }
    return count;
}

private static void dfs(char[][] grid, int i, int j) {
    int row = grid.length;
    int column = grid[0].length;
    if (i - 1 >= 0 && i + 1 < row && j - 1 >= 0 && j + 1 < column) {
        if (grid[i - 1][j] == '@') {
            grid[i - 1][j] = '#';
            dfs(grid, i - 1, j);
        }
        if (grid[i + 1][j] == '@') {
            grid[i + 1][j] = '#';
            dfs(grid, i + 1, j);
        }
        if (grid[i][j - 1] == '@') {
            grid[i][j - 1] = '#';
            dfs(grid, i, j - 1);
        }
        if (grid[i][j + 1] == '@') {
            grid[i][j + 1] = '#';
            dfs(grid, i, j + 1);
        }
    }
}

public static int countOilDeposits(char[][] grid) {
    // Initialize the number of distinct oil deposits to 0
    int numDeposits = 0;

    // Loop through each row of the grid
    for (int row = 0; row < grid.length; row++) {
        // Loop through each column of the grid
        for (int col = 0; col < grid[row].length; col++) {
            // If the current cell contains an oil deposit
            if (grid[row][col] == '@') {
                // Check the neighboring cells
                boolean found = false;
                for (int i = -1; i <= 1; i++) {
                    for (int j = -1; j <= 1; j++) {
                        // If the neighboring cell contains an oil deposit
                        if (grid[row + i][col + j] == '@') {
                            found = true;
                            break;
                        }
                    }
                }

                // If no matching oil deposits were found, increment the number of distinct oil deposits
                if (!found) {
                    numDeposits++;
                }
            }
        }
    }

    return numDeposits;
}

