public double trimMean(int[] arr) {
    double sum = 0;
    int len = arr.length;
    int count = (int) Math.ceil(len * 0.05);
    int start = 0, end = len - 1;

    // Calculate sum of first 5% of elements
    for (int i = 0; i < count; i++) {
        sum += arr[i];
    }

    // Calculate sum of last 5% of elements
    for (int i = len - count; i < len; i++) {
        sum += arr[i];
    }

    // Calculate mean of middle 90% of elements
    for (int i = start + count; i <= end - count; i++) {
        sum += arr[i];
    }

    return sum / (len - 2 * count);
}

