    int removeSmall = (int) Math.round(arr.length * 0.05);
    int removeLarge = (int) Math.round(arr.length * 0.05);

    // Remove the smallest and largest elements
    int[] remaining = new int[arr.length - removeSmall - removeLarge];
    for (int i = removeSmall; i < arr.length - removeLarge; i++) {
        remaining[i - removeSmall] = arr[i];
    }

    // Calculate the mean of the remaining elements
    double sum = 0;
    for (int num : remaining) {
        sum += num;
    }
    return sum / (double) remaining.length;
}

