            this.val = val;
            this.hasApple = hasApple;
        }

public String sortString(String s) {
    if (s == null) {
      throw new IllegalArgumentException("s must not be null");
    }
    char[] chars = s.toCharArray();
    int n = chars.length;
    char[] sortedChars = new char[n];
    // Step 1: Sort the first half of the string by appending the smallest character first, followed by the
    // smallest character greater than the previous character, and so on. Repeat this process until all
    // characters have been appended.
    int start = 0;
    int end = n / 2;
    for (int i = 0; i < n; i++) {
      if (i % 2 == 0) {
        // Descending
        start = n - i - 1;
        end = n;
      } else {
        // Ascending
        start = 0;
        end = n - i - 1;
      }
      for (int j = start; j <= end; j++) {
        sortedChars[i] = chars[j];
      }
    }
    // Step 2: Sort the second half of the string by appending the largest character first, followed by the
    // second largest character, and so on. Repeat this process until all characters have been appended.
    int rstart = 0;
    int rend = n - 1;
    for (int i = n - 1; i >= n / 2; i--) {
      if (i % 2 != 0) {
        // Ascending
        rstart = 0;
        rend = n - i - 1;
      } else {
        // Descending
        rstart = n - 1;
        rend = n;
      }
      for (int j = rstart; j >= rend; j--) {
        sortedChars[i] = chars[j];
      }
    }
    return new String(sortedChars);
  }

