        ArrayList<Character> list = new ArrayList<>();
        while (list.size() < s.length()) {
            char smallest = getSmallest(s);
            char largest = getLargest(s);
            list.add(smallest);
            list.add(largest);
            s = s.replaceFirst(String.valueOf(smallest), "");
            s = s.replaceFirst(String.valueOf(largest), "");
        }
        return list.toString();
    }

private char getSmallest(String s) {
        char smallest = 'z';
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) < smallest) {
                smallest = s.charAt(i);
            }
        }
        return smallest;
    }

private char getLargest(String s) {
        char largest = 'a';
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) > largest) {
                largest = s.charAt(i);
            }
        }
        return largest;
    }

public String sortString(String s) {
    if (s == null || s.length() < 2) {
        return s;
    }
    char[] array = s.toCharArray();
    char smallest = array[0];
    char largest = array[s.length() - 1];
    char[] result = new char[s.length()];
    int indexSmallest = 0;
    int indexLargest = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = array[i];
        if (c < smallest) {
            smallest = c;
            indexSmallest = i;
        } else if (c > largest) {
            largest = c;
            indexLargest = i;
        }
    }
    result[0] = smallest;
    result[s.length() - 1] = largest;
    for (int i = 1; i < s.length() - 1; i++) {
        char c = array[i];
        if (c < result[i - 1]) {
            result[i] = c;
        } else {
            result[i] = result[i - 1];
            result[i - 1] = c;
        }
    }
    return new String(result);
}

