public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int min = Integer.MAX_VALUE;
    int max = Integer.MIN_VALUE;

    for (int i = 0; i < n; i++) {
        min = Math.min(min, arr[i]);
    }

    for (int i = 0; i < n; i++) {
        max = Math.max(max, arr[i]);
    }

    if (min == max) {
        return 0;
    }

    int target = (min + max) / 2;
    int count = 0;

    for (int i = 0; i < n; i++) {
        if (arr[i] < target) {
            count += target - arr[i];
        } else if (arr[i] > target) {
            count += arr[i] - target;
        }
    }

    return count;
}

public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int minCount = Integer.MAX_VALUE;
    for (int x = 0; x < n; x++) {
        for (int y = 0; y < n; y++) {
            if (x == y) continue;
            int count = 0;
            for (int i = 0; i < n; i++) {
                if (arr[i] == arr[x]) {
                    count++;
                }
            }
            minCount = Math.min(minCount, count);
        }
    }
    return minCount;
}

