public static double calculateProbability(int n) {
	// Calculate the number of possible seating arrangements
	int numArrangements = 1;
	for (int i = 1; i <= n; i++) {
		numArrangements *= i;
	}

	// Calculate the number of favorable seating arrangements
	int numFavorableArrangements = 1;
	for (int i = 1; i <= n; i++) {
		if (i == n) {
			numFavorableArrangements *= 1; // last passenger sits in their own seat
		} else {
			numFavorableArrangements *= (n - i); // last passenger sits in a different seat
		}
	}

	// Calculate the probability
	return (double) numFavorableArrangements / numArrangements;
}

