    int[][] vertical = new int[m][n];
    int[][] diagonal = new int[2 * m - 1][2 * n - 1];
    int[][] antiDiagonal = new int[2 * m - 1][2 * n - 1];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horizontal[i][j]++;
                vertical[i][j]++;
                diagonal[i][j]++;
                antiDiagonal[i][j]++;
                if (i > 0) {
                    horizontal[i][j] += horizontal[i - 1][j];
                    vertical[i][j] += vertical[i - 1][j];
                    diagonal[i][j] += diagonal[i - 1][j];
                    antiDiagonal[i][j] += antiDiagonal[i - 1][j];
                }
            } else {
                horizontal[i][j] = 0;
                vertical[i][j] = 0;
                diagonal[i][j] = 0;
                antiDiagonal[i][j] = 0;
            }
        }
    }

    int maxLength = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            int tempLength = 0;
            if (horizontal[i][j] > tempLength) {
                tempLength = horizontal[i][j];
            }
            if (vertical[i][j] > tempLength) {
                tempLength = vertical[i][j];
            }
            if (diagonal[i][j] > tempLength) {
                tempLength = diagonal[i][j];
            }
            if (antiDiagonal[i][j] > tempLength) {
