public static int calculateEnergy(String s) {
    int energy = 0;
    int count = 1;
    int maxCount = 0;
    char lastChar = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == lastChar) {
            count++;
        } else {
            lastChar = c;
            count = 1;
        }
        if (count > maxCount) {
            maxCount = count;
        }
    }
    return maxCount;
}

public static int calculateEnergy(String s) {
