        int currentLength = 0;
        int center = 0;
        while (center < s.length() - 1) {
            int i = center, j = center + 1;
            while (i >= 0 && j < s.length() && s.charAt(i) == s.charAt(j)) {
                currentLength++;
                i--;
                j++;
            }
            if (currentLength > energy) {
                energy = currentLength;
            }
            center = j;
            currentLength = 0;
        }
        return energy;
    }

