public static int minPerfectSquareSum(int n) {
    int count = 0;
    while (n > 0) {
        int root = (int) Math.sqrt(n);
        count++;
        n -= root * root;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    int[] nums = new int[n + 1];
    int count = 0;

    for (int i = 1; i <= n; i++) {
        if (isPerfectSquare(i)) {
            count++;
            nums[i] = count;
        } else {
            nums[i] = nums[i - 1];
        }
    }

    return count;
}

private static boolean isPerfectSquare(int n) {
    int root = (int) Math.sqrt(n);
    return root * root == n;
}

public static int minPerfectSquareSum(int n) {
    int[] perfectSquares = new int[n + 1];
    perfectSquares[0] = 0;
    for (int i = 1; i <= n; i++) {
        perfectSquares[i] = i * i;
    }
    int minSquares = Integer.MAX_VALUE;
    for (int i = 1; i <= n; i++) {
        int numSquares = 0;
        int sum = 0;
        for (int j = i; j <= n; j++) {
            sum += perfectSquares[j];
            if (sum > n) {
                break;
            }
            numSquares++;
            if (sum == n) {
                minSquares = Math.min(minSquares, numSquares);
                break;
            }
        }
    }
    return minSquares;
}

public static int minPerfectSquareSum(int n) {
    List<Integer> perfectSquares = new ArrayList<>();
    for (int i = 1; i <= Math.sqrt(n); i++) {
        int square = i * i;
        if (square <= n) {
            perfectSquares.add(square);
        }
    }
    int minCount = Integer.MAX_VALUE;
    for (int i = 0; i < perfectSquares.size(); i++) {
        int count = 0;
        for (int j = i; j < perfectSquares.size(); j++) {
            count++;
            if (perfectSquares.get(j) > n) {
                break;
            }
            if (perfectSquares.get(j) == n) {
                minCount = Math.min(minCount, count);
                break;
            }
        }
    }
    return minCount == Integer.MAX_VALUE ? -1 : minCount;
}

public static int minPerfectSquareSum(int n) {
    int[] perfectSquares = new int[n];
    perfectSquares[0] = 0;
    for (int i = 1; i < n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j <= i; j++) {
            int square = perfectSquares[i - j] + j * j;
            if (square <= i) {
                min = Math.min(min, square);
            }
        }
        perfectSquares[i] = min;
    }
    return perfectSquares[n - 1];
}

